package com.smritisathi.app.voice;public class VoiceIntents {public static String match(String s){if(s==null)return"unknown";String x=s.toLowerCase();if(x.contains("what do i have to do")||x.contains("today's schedule")||x.contains("my day")||x.contains("what is today"))return"reminders";if(x.contains("medicine")||x.contains("pill")||x.contains("medication")||x.contains("tablet"))return"medicine";if(x.contains("game")||x.contains("memory")||x.contains("play")||x.contains("puzzle"))return"game";return"unknown";}}
